<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Szablon · '.$template['name'];?>
<div class="page-head"><div><p class="eyebrow">Szablon</p><h1><?=Html::e($template['name'])?></h1></div><a class="button secondary" href="<?=Html::e(Url::to('/admin/templates'))?>">Wróć</a></div><?php if(isset($_GET['saved'])):?><div class="alert success">Zapisano.</div><?php endif;?><?php if(isset($_GET['error'])):?><div class="alert danger">Operacja została odrzucona.</div><?php endif;?><section class="card section-card"><form method="post" class="grid compact-form"><?=Csrf::field()?><label>Nazwa<input name="name" value="<?=Html::e($template['name'])?>" maxlength="150" required></label><label>Opis<input name="description" value="<?=Html::e($template['description']??'')?>" maxlength="255"></label><label>Labels<input name="labels" value="<?=Html::e(implode(', ',json_decode((string)($template['labels_json']??'[]'),true)?:[]))?>"></label><label class="span-all">Properties JSON<textarea name="properties" rows="3"><?=Html::e($template['properties_json']??'[]')?></textarea></label><label class="span-all">Treść HTML<textarea name="content" rows="12"><?=Html::e($template['content'])?></textarea></label><div class="form-action"><button class="button">Zapisz</button></div></form><div class="actions"><form method="post" action="<?=Html::e(Url::to('/admin/templates/'.$template['id'].'/clone'))?>"><?=Csrf::field()?><button class="button secondary">Klonuj</button></form><?php if(empty($template['is_system'])):?><form method="post" action="<?=Html::e(Url::to('/admin/templates/'.$template['id'].'/archive'))?>" onsubmit="return confirm('Zarchiwizować szablon?')"><?=Csrf::field()?><button class="button secondary">Archiwizuj</button></form><?php endif;?></div></section>
